commands.command:
node --import tsx --input-type=module - <<'JS'
import {generateDrizzleJson,generateMigration} from 'drizzle-kit/api';
import * as schema from './src/db/schema.ts';
import {readFileSync} from 'node:fs';
const previous=JSON.parse(readFileSync('drizzle/meta/0013_snapshot.json','utf8'));
const delta=await generateMigration(previous,generateDrizzleJson(schema,previous.id));
if(delta.length)throw new Error(JSON.stringify(delta));
console.log('Schema matches 0013 snapshot; zero generated migration statements.');
JS
